function getFoodImageUrl(name, categoryTitle) {
  return getFoodImage(name, categoryTitle);
}

export const menuCategories = rawMenuCategories.map((category) => ({
  ...category,
  items: category.items.map((item) => ({
    ...item,
    image:
      typeof item.image === "string" && /^https?:\/\//i.test(item.image)
        ? item.image
        : getFoodImageUrl(item.name, category.title),
  })),
}));